func (d *dnsResolver) watcher() {
	defer d.wg.Done()
	for {
		select {
		case <-d.ctx.Done():
			return
		case <-d.rn:
		}

		state, err := d.lookup()
		if err != nil {
			d.cc.ReportError(err)
		} else {
			d.cc.UpdateState(*state)
		}

		// Wait before resolving again, even when no explicit request arrives.
		t := time.NewTimer(minDNSResRate)
		select {
		case <-t.C:
			d.ResolveNow(resolver.ResolveNowOptions{})
		case <-d.ctx.Done():
			t.Stop()
			return
		}
	}
}

